import React, { useState, useEffect } from 'react';
import api from '../services/api';

const Store2 = () => {
    const [stocks, setStocks] = useState([]);
    const [loading, setLoading] = useState(true);
    const [error, setError] = useState(null);
    const [newStock, setNewStock] = useState({ productName: '', quantity: '', price: '' });
    const [selectedStock, setSelectedStock] = useState(null);

    useEffect(() => {
        fetchStocks();
    }, []);

    const fetchStocks = async () => {
        try {
            const response = await api.store2.getAllStock();
            setStocks(response.data);
            setLoading(false);
        } catch (err) {
            setError('Stok verileri yüklenirken bir hata oluştu');
            setLoading(false);
        }
    };

    const handleCreateStock = async (e) => {
        e.preventDefault();
        try {
            await api.store2.createStock(newStock);
            setNewStock({ productName: '', quantity: '', price: '' });
            fetchStocks();
        } catch (err) {
            setError('Stok oluşturulurken bir hata oluştu');
        }
    };

    const handleUpdateStock = async (e) => {
        e.preventDefault();
        if (!selectedStock) return;
        try {
            await api.store2.updateStock(selectedStock);
            setSelectedStock(null);
            fetchStocks();
        } catch (err) {
            setError('Stok güncellenirken bir hata oluştu');
        }
    };

    const handleCreateSale = async (stockId) => {
        try {
            await api.store2.createSale({ stockId });
            fetchStocks();
        } catch (err) {
            setError('Satış oluşturulurken bir hata oluştu');
        }
    };

    const handleCreateReturn = async (saleId) => {
        try {
            await api.store2.createReturn({ saleId });
            fetchStocks();
        } catch (err) {
            setError('İade oluşturulurken bir hata oluştu');
        }
    };

    if (loading) return <div>Yükleniyor...</div>;
    if (error) return <div className="error">{error}</div>;

    return (
        <div className="store-container">
            <h2>Store 2 Yönetimi</h2>
            
            {/* Yeni Stok Oluşturma Formu */}
            <div className="form-section">
                <h3>Yeni Stok Ekle</h3>
                <form onSubmit={handleCreateStock}>
                    <input
                        type="text"
                        placeholder="Ürün Adı"
                        value={newStock.productName}
                        onChange={(e) => setNewStock({...newStock, productName: e.target.value})}
                    />
                    <input
                        type="number"
                        placeholder="Miktar"
                        value={newStock.quantity}
                        onChange={(e) => setNewStock({...newStock, quantity: e.target.value})}
                    />
                    <input
                        type="number"
                        placeholder="Fiyat"
                        value={newStock.price}
                        onChange={(e) => setNewStock({...newStock, price: e.target.value})}
                    />
                    <button type="submit">Stok Ekle</button>
                </form>
            </div>

            {/* Stok Listesi */}
            <div className="data-grid">
                {stocks.map((stock) => (
                    <div key={stock.id} className="data-card">
                        <h3>{stock.productName}</h3>
                        <p>Miktar: {stock.quantity}</p>
                        <p>Fiyat: {stock.price}</p>
                        <div className="card-actions">
                            <button onClick={() => setSelectedStock(stock)}>Düzenle</button>
                            <button onClick={() => handleCreateSale(stock.id)}>Satış Yap</button>
                        </div>
                    </div>
                ))}
            </div>

            {/* Stok Güncelleme Modal */}
            {selectedStock && (
                <div className="modal">
                    <div className="modal-content">
                        <h3>Stok Güncelle</h3>
                        <form onSubmit={handleUpdateStock}>
                            <input
                                type="text"
                                placeholder="Ürün Adı"
                                value={selectedStock.productName}
                                onChange={(e) => setSelectedStock({
                                    ...selectedStock,
                                    productName: e.target.value
                                })}
                            />
                            <input
                                type="number"
                                placeholder="Miktar"
                                value={selectedStock.quantity}
                                onChange={(e) => setSelectedStock({
                                    ...selectedStock,
                                    quantity: e.target.value
                                })}
                            />
                            <input
                                type="number"
                                placeholder="Fiyat"
                                value={selectedStock.price}
                                onChange={(e) => setSelectedStock({
                                    ...selectedStock,
                                    price: e.target.value
                                })}
                            />
                            <div className="modal-actions">
                                <button type="submit">Güncelle</button>
                                <button type="button" onClick={() => setSelectedStock(null)}>İptal</button>
                            </div>
                        </form>
                    </div>
                </div>
            )}
        </div>
    );
};

export default Store2;
